// Request-stage enforcement for the fresh, Runner-owned Chromium browser.
// Frame attribution uses public Page events only; never query a paused renderer.
export async function installNavigationPolicy({
  browser,
  context,
  hostAllowed,
  latchNavigation,
  observe,
  onError,
  signal,
  deadline,
}) {
  const frames = new Map(),
    pages = new Map(),
    pending = new Map();
  let closing = false,
    failure,
    resolveFailure;
  const failed = new Promise((resolve) => {
    resolveFailure = resolve;
  });
  const fail = (error) => {
    if (closing || failure) return;
    failure = error instanceof Error ? error : new Error(String(error));
    onError(`Navigation Fetch failure: ${failure.message}`);
    resolveFailure(failure);
  };
  // Resolving the failure latch avoids an unhandled rejected event promise.
  const wait = (promise) =>
    Promise.race([
      promise,
      failed.then((error) => {
        throw error;
      }),
    ]);
  const abort = () => fail(new Error("Navigation guard interrupted"));
  const timer = setTimeout(
    () => fail(new Error("Time limit")),
    Math.max(1, deadline - Date.now()),
  );
  signal?.addEventListener("abort", abort, { once: true });
  if (signal?.aborted) abort();
  let session;
  const remove = (id) => {
    const removed = new Set([id]);
    for (const current of removed)
      for (const [child, record] of frames)
        if (record.parent === current) removed.add(child);
    for (const current of removed) frames.delete(current);
  };
  const invalidate = (owner) => {
    for (const [id, record] of frames)
      if (record.owner === owner) frames.delete(id);
  };
  const classify = (id) => {
    const seen = new Set();
    let record = frames.get(id);
    const owner = record?.owner;
    if (!record || !pages.has(owner)) return "unknown";
    const child = Boolean(record.parent);
    while (record.parent) {
      if (seen.has(record.parent)) return "unknown";
      seen.add(record.parent);
      record = frames.get(record.parent);
      if (!record || record.owner !== owner) return "unknown";
    }
    return child ? "subframe" : "main-frame";
  };
  const arm = async (page, primeTree = false) => {
    if (pages.has(page) || closing) return;
    const entry = {};
    pages.set(page, entry);
    const buffered = [];
    let primed = false;
    const apply = (kind, event) => {
      if (kind === "detach") {
        // Chromium's OOPIF renderer swap preserves the logical frame/parent.
        // A remove destroys the logical frame and all known descendants.
        if (event.reason !== "swap") remove(event.frameId);
        return;
      }
      const id = event.frameId ?? event.frame?.id;
      const parent = event.parentFrameId ?? event.frame?.parentId ?? null;
      if (
        typeof id !== "string" ||
        !id ||
        parent === id ||
        (kind === "attach" && (typeof parent !== "string" || !parent))
      ) {
        if (id) remove(id);
        return;
      }
      const previous = frames.get(id);
      if (previous && (previous.owner !== page || previous.parent !== parent))
        remove(id);
      frames.set(id, { owner: page, parent });
    };
    const event = (kind, value) => {
      try {
        if (!primed) buffered.push([kind, value]);
        else apply(kind, value);
      } catch (error) {
        fail(error);
      }
    };
    try {
      const cdp = await wait(context.newCDPSession(page));
      entry.session = cdp;
      cdp.on("Page.frameAttached", (value) => event("attach", value));
      cdp.on("Page.frameNavigated", (value) => event("navigate", value));
      cdp.on("Page.frameDetached", (value) => event("detach", value));
      const closed = () => {
        invalidate(page);
        pages.delete(page);
      };
      page.on("close", closed);
      cdp.on("close", () => {
        closed();
        if (!closing && !page.isClosed())
          fail(new Error("Frame attribution session closed"));
      });
      await wait(cdp.send("Page.enable"));
      // Only the initial blank pages are queried, before browser Fetch exists.
      // Later pages use events: even their first Document can already be paused.
      if (primeTree) {
        const { frameTree } = await wait(cdp.send("Page.getFrameTree"));
        if (page.isClosed() || !pages.has(page)) return;
        const snapshot = (tree) => {
          apply("navigate", { frame: tree.frame });
          for (const child of tree.childFrames ?? []) snapshot(child);
        };
        snapshot(frameTree);
      }
      for (const [kind, value] of buffered) apply(kind, value);
      primed = true;
    } catch (error) {
      invalidate(page);
      if (!page.isClosed()) fail(error);
    }
  };
  const onPage = (page) => {
    void arm(page).catch(fail);
  };
  const beginCleanup = () => {
    closing = true;
    clearTimeout(timer);
    signal?.removeEventListener("abort", abort);
    context.off("page", onPage);
    // Do not disable Fetch or detach a live session: that can release pauses.
    // The owned browser/context close is the enforcement lifetime boundary.
    for (const [requestId, record] of pending)
      if (!record.dispatched) {
        record.dispatched = true;
        void session
          ?.send("Fetch.failRequest", { requestId, errorReason: "Aborted" })
          .catch(() => {});
      }
  };
  try {
    session = await wait(browser.newBrowserCDPSession());
    session.on("close", () =>
      fail(new Error("Browser interception session closed")),
    );
    session.on("Fetch.requestPaused", (event) => {
      if (!event || typeof event.requestId !== "string" || !event.requestId) {
        fail(new Error("Malformed paused Document request identity"));
        return;
      }
      const record = { dispatched: false };
      pending.set(event.requestId, record);
      void (async () => {
        const allowedHost = hostAllowed(event.request.url);
        const classification = allowedHost
          ? "host-allowed"
          : classify(event.frameId);
        const allowed =
          !failure &&
          !closing &&
          (allowedHost || classification === "subframe");
        observe(classification, allowed);
        if (!allowed && !failure && !closing)
          latchNavigation(event.request.url, classification, "fetch");
        record.dispatched = true;
        await wait(
          session.send(
            allowed ? "Fetch.continueRequest" : "Fetch.failRequest",
            {
              requestId: event.requestId,
              ...(!allowed ? { errorReason: "BlockedByClient" } : {}),
            },
          ),
        );
      })()
        .catch(fail)
        .finally(() => pending.delete(event.requestId));
    });
    for (const page of context.pages()) await arm(page, true);
    if (failure) throw failure;
    context.on("page", onPage);
    await wait(
      session.send("Fetch.enable", {
        patterns: [
          {
            urlPattern: "*",
            resourceType: "Document",
            requestStage: "Request",
          },
        ],
      }),
    );
    return { wait, beginCleanup };
  } catch (error) {
    fail(error);
    beginCleanup();
    throw error;
  }
}
